-- POSTMORTEM.EXPLORER.EVAL_EXPLORER (table)
-- Evaluation set (questions and ground truth) of the retired Post-Mortem Explorer agent. The only object left
-- in EXPLORER.
--
-- Not exported from EXPLORER: the AI_OBS_OUTPUT_PARSER_* functions and the _PEP_YAML_READER file format
-- (auto-generated by agent observability).
-- WARNING: CREATE OR REPLACE TABLE drops existing data. Run only on a fresh, empty database.

create or replace TABLE POSTMORTEM.EXPLORER.EVAL_EXPLORER (
	INPUT_QUERY VARCHAR(16777216),
	GROUND_TRUTH VARIANT
);
